import{_ as a,o as t,c as o,a5 as n}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"UC — Add Hastag Collection","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/add-hashtag-collection/spec.md","filePath":"feature/content-task-workflow/add-hashtag-collection/spec.md"}'),i={name:"feature/content-task-workflow/add-hashtag-collection/spec.md"};function r(s,e,c,d,l,h){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="uc-—-add-hastag-collection" tabindex="-1">UC — Add Hastag Collection <a class="header-anchor" href="#uc-—-add-hastag-collection" aria-label="Permalink to &quot;UC — Add Hastag Collection&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.6.19</td></tr><tr><td>Feature</td><td>Add Hastag Collection</td></tr><tr><td>Domain</td><td>Content &amp; Workflow (FR 3.6)</td></tr><tr><td>Role</td><td>CREATOR, CLIENT</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Draft — BA confirmed, chưa code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Thêm hashtag mới vào Collection, phân loại rõ mục đích sử dụng.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Creator hoặc Client, tôi muốn thêm hashtag mới vào kho, để dùng lại cho các bài đăng sau.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>Form nhập <code>tag</code>, chọn <code>purpose</code> (ví dụ: brand, campaign, trending, event-specific).</li><li>Client thêm → tự động <code>isRequired=true</code> nếu đánh dấu đặc thù sự kiện.</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Nút &#39;Thêm hashtag&#39; trong <code>/workspaces/:id/hashtags</code>.</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/workspaces/{id}/hashtags</span></span>
<span class="line"><span>{ &quot;tag&quot;: &quot;string&quot;, &quot;purpose&quot;: &quot;string&quot;, &quot;isRequired&quot;?: boolean }</span></span>
<span class="line"><span>→ 201 { &quot;success&quot;: true, &quot;data&quot;: { &quot;id&quot;, &quot;tag&quot; } }</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>Hashtag trùng đã tồn tại trong Workspace → 409 <code>HASHTAG_ALREADY_EXISTS</code>.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Không có edge case đặc biệt.</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Thêm thành công, phân loại đúng purpose.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không có.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../BA/05-content-task-workflow.html">05-content-task-workflow.md</a></p><h2 id="implementation-contract-—-2026-10-10" tabindex="-1">Implementation contract — 2026-10-10 <a class="header-anchor" href="#implementation-contract-—-2026-10-10" aria-label="Permalink to &quot;Implementation contract — 2026-10-10&quot;">​</a></h2><p>The revised <code>tuan-research/spec</code> FR takes precedence over the legacy role table above. This delivery covers Add + View + Remove. One row represents one hashtag, not a named group. Active CREATOR, CLIENT and MANAGER members may view and add in an active workspace; client-profile membership is supported. Owner/admin status alone grants no content access. No Apply, Update, AI call or Post mutation is included. Remove soft-deletes the collection entry and records deletedBy/deletedAt; Manager may remove any entry, Creator may remove own ordinary entries or any required Client entry, and Client may remove own entries.</p><p>POST <code>/api/v1/workspaces/{workspaceId}/hashtags</code> accepts <code>tag</code>, <code>purpose</code>. Purpose values: BRAND, CAMPAIGN, TRENDING, EVENT_SPECIFIC. In this delivery, EVENT_SPECIFIC means a required tag scoped to a MediaCampaign, since the repository has no Event entity. Only CLIENT may create one. The backend verifies its campaign belongs to the requested workspace; this mapping should move to Event if/when that entity is introduced. Tags: trim, remove one leading #, NFC Unicode normalization, letters/marks/digits/underscore, 1–100 characters; retain accents and display case, lowercase ROOT for duplicate matching. An active normalized tag is unique within its workspace. Duplicate races return 409 HASHTAG_ALREADY_EXISTS. Creator identity/time comes from the server. GET uses q (max 100), purpose, isRequired, page (default 0), size (default 20, max 100). POST also accepts isRequired and campaignId for an event-specific required tag. GET accepts campaignId as an optional scope filter. Response data contains items, page, size, totalElements and totalPages. Each item includes id, workspaceId, tag, purpose, addedBy, addedByName, isRequired, campaignId, version and createdAt. <code>version</code> supports reconfirmation if an entry changes before removal. DELETE <code>/api/v1/workspaces/{workspaceId}/hashtags/{hashtagId}</code> accepts optional <code>expectedVersion</code>; successful removal returns 200 with null data. Removed entries no longer appear in the active collection and existing post snapshots remain unchanged. Bad input returns 400; unauthenticated returns 401; unauthorized/inactive workspace returns 403.</p><p>UI: collection page and Library hashtag tab use the same real collection feature. Existing hashtag-groups URL remains compatible; <code>/workspaces/:id/hashtags</code> is canonical. Loading, empty, filtered-empty, retry, saving, duplicate and denied states are distinct. A workspace switch resets local form/filters and query keys include workspace and account. Successful creation refreshes that workspace collection. Failed saves retain input.</p><p>All labels use parallel vi/en keys under <code>hashtagGroups.collection</code>: title, description, add, tag, purpose, purposes.*, required, optional, creator, createdAt, search, all, allRequirements, empty, noResults, loading, retry, loadError, saveError, duplicate, invalid, denied, selectWorkspace, save, cancel, added, previous, next, page. Use semantic theme tokens in light/dark, labeled inputs and keyboard-operable controls.</p>`,27)])])}const m=a(i,[["render",r]]);export{p as __pageData,m as default};
